<!-- GSAP horizontal pinned — transform only, Lenis synced -->
<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js"></script>
<script>
(function(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if(typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return;
  gsap.registerPlugin(ScrollTrigger);
  function initFeat(){
    var lenis = window.__lenis;
    if(lenis && lenis.on) lenis.on('scroll', ScrollTrigger.update);
    if(!window.matchMedia('(min-width:1024px)').matches) return;
    var track = document.getElementById('track-feat');
    var pin = document.getElementById('pin-feat');
    if(!track || !pin) return;
    var getScroll = function(){ return -(track.scrollWidth - window.innerWidth); };
    gsap.to(track, { x: getScroll, ease:"none", scrollTrigger:{ trigger: pin, pin:true, scrub:1, start:"top top", end:function(){ return "+=" + (track.scrollWidth - window.innerWidth); }, invalidateOnRefresh:true }});
    gsap.to("#progress-feat", { width:"100%", ease:"none", scrollTrigger:{ trigger: pin, start:"top top", end:function(){ return "+=" + (track.scrollWidth - window.innerWidth); }, scrub:0.6 }});
    window.addEventListener('load', function(){ ScrollTrigger.refresh(); });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', initFeat); } else { setTimeout(initFeat, 180); }
})();
</script>
